CREATE OR REPLACE FUNCTION public.grava_evento_corridas_percursos()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE

var_data_percurso   date;
var_num_dias        integer;
var_arr_percursos   numeric[];
var_unidade         varchar;
prc                 numeric;


BEGIN

    if NEW.categorias is distinct from  OLD.categorias then
        delete from  tb_evento_corridas_percursos where id_evento = NEW.id_evento and percurso_bloqueado = false;

        if NEW.categorias is null then
            return NEW;
        end if;

        if position('km' in lower(NEW.categorias)) > 0 then
            var_unidade := 'km';
        else
            if position('milha' in lower(NEW.categorias)) > 0 or position('milha' in lower(NEW.nome_evento)) > 0  then
                var_unidade := 'mi';
            else
                var_unidade := '--';
            end if;
        end if;

        var_arr_percursos := array_remove(string_to_array(regexp_replace(NEW.categorias, '[^0-9.,]','','g'),','),'');
        var_num_dias := (NEW.data_final - NEW.data_inicial) + 1;

        foreach prc in array var_arr_percursos loop
            if prc < 21 then
            var_data_percurso := NEW.data_inicial;
            else
                if prc < 42 then
                    if var_num_dias = 1 then
                    var_data_percurso := NEW.data_inicial;
                    else
                    var_data_percurso := NEW.data_inicial + 1;
                    end if;
                else
                    if var_num_dias = 1 then
                    var_data_percurso := NEW.data_inicial;
                    else
                    var_data_percurso := NEW.data_final;
                    end if;
                end if;
            end if;

            insert into tb_evento_corridas_percursos
            ( percurso_evento, unidade_de_medida, id_evento, data_percurso, tipo_corrida )
            values
            ( prc, var_unidade, NEW.id_evento, var_data_percurso, NEW.tipo_corrida )
            on CONFLICT (percurso_evento, id_evento) DO UPDATE
            SET
                percurso_evento   = excluded.percurso_evento,
                unidade_de_medida = excluded.unidade_de_medida,
                id_evento         = excluded.id_evento,
                data_percurso     = excluded.data_percurso
            -- A edição manual bloqueada prevalece sobre a geração automática.
            WHERE NOT tb_evento_corridas_percursos.percurso_bloqueado;
        end loop;
    end if;

    if NEW.organizador is distinct from OLD.organizador then
        insert into tb_evento_corridas_fornecedores
            ( id_evento, id_fornecedor_tipo, id_fornecedor )
        select
            NEW.id_evento,
            1,
            fo.id_fornecedor
        from  tb_fornecedores fo
            where to_tsvector(unaccent(fo.nome_fornecedor)) @@ plainto_tsquery('portuguese',unaccent(trim(NEW.organizador)))
        on CONFLICT (id_evento, id_fornecedor_tipo, id_fornecedor) DO UPDATE
        SET
            id_fornecedor   = excluded.id_fornecedor;
    end if;

RETURN NEW;
END
$function$
CREATE OR REPLACE PROCEDURE public.grava_evento_corridas_percursos(IN p_id_evento integer, IN p_nome_evento character varying, IN p_data_ini date, IN p_data_fim date, IN p_categorias character varying)
 LANGUAGE plpgsql
AS $procedure$
DECLARE

var_percurso        integer;
var_data_percurso   date;
var_num_dias        integer;
var_arr_percursos   numeric[];
var_unidade         varchar;
prc                 integer;

BEGIN
    if p_categorias is null then
        return;
    end if;
    if position('km' in lower(p_categorias)) > 0 then
        var_unidade := 'km';
    else
        if position('milha' in lower(p_categorias)) > 0 or position('milha' in lower(p_nome_evento)) > 0  then
            var_unidade := 'mi';
        else
            var_unidade := '--';
        end if;
    end if;

    var_arr_percursos := array_remove(string_to_array(regexp_replace(p_categorias, '[^0-9.,]','','g'),','),'');
    var_num_dias := (p_data_fim - p_data_ini) + 1;

    foreach prc in array var_arr_percursos loop
        if prc < 21 then
           var_data_percurso := p_data_ini;
        else
            if prc < 42 then
                if var_num_dias = 1 then
                   var_data_percurso := p_data_ini;
                 else
                   var_data_percurso := p_data_ini + 1;
                end if;
            else
                if var_num_dias = 1 then
                   var_data_percurso := p_data_ini;
                 else
                   var_data_percurso := p_data_fim;
                end if;
            end if;
        end if;

        insert into tb_evento_corridas_percursos
          ( percurso_evento, unidade_de_medida, id_evento, data_percurso )
        values
          ( prc, var_unidade, p_id_evento, var_data_percurso )
        on CONFLICT (percurso_evento, id_evento) DO UPDATE
        SET
            percurso_evento   = excluded.percurso_evento,
            unidade_de_medida = excluded.unidade_de_medida,
            id_evento         = excluded.id_evento,
            data_percurso     = excluded.data_percurso
            -- A edição manual bloqueada prevalece sobre a geração automática.
            WHERE NOT tb_evento_corridas_percursos.percurso_bloqueado;
    end loop;

END
$procedure$
CREATE OR REPLACE FUNCTION public.registra_evento_fatos_historico()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
    antes jsonb := '{}'::jsonb;
    depois jsonb := '{}'::jsonb;
    diferencas jsonb := '{}'::jsonb;
    campos text[];
    campo text;
    tipo text;
    entidade_id integer;
    evento_id integer;
    evento_anterior integer;
BEGIN
    IF TG_TABLE_SCHEMA <> 'public' OR TG_NARGS <> 0 OR TG_WHEN <> 'AFTER' OR TG_LEVEL <> 'ROW' THEN
        RAISE EXCEPTION 'Unsupported factual history trigger';
    END IF;
    IF TG_TABLE_NAME = 'tb_evento_corridas' THEN
        tipo := 'evento';
        campos := ARRAY['id_evento','nome_evento','tag','data_inicial','data_final','cidade','estado','pais','endereco','coordenadas','categorias','tipo_corrida','status_evento','url_hotsite','url_regulamento','url_inscricao','ativo'];
    ELSIF TG_TABLE_NAME = 'tb_evento_corridas_percursos' THEN
        tipo := 'percurso';
        campos := ARRAY['id_evento_percurso','id_evento','percurso_evento','unidade_de_medida','data_percurso','hora_largada','hora_corte','tipo_corrida'];
    ELSE
        RAISE EXCEPTION 'Unsupported factual history table';
    END IF;
    IF TG_OP <> 'INSERT' THEN antes := to_jsonb(OLD); END IF;
    IF TG_OP <> 'DELETE' THEN depois := to_jsonb(NEW); END IF;
    FOREACH campo IN ARRAY campos LOOP
        IF TG_OP <> 'UPDATE' OR antes->campo IS DISTINCT FROM depois->campo THEN
            diferencas := diferencas || jsonb_build_object(campo,
                jsonb_build_object('antes', antes->campo, 'depois', depois->campo));
        END IF;
    END LOOP;
    IF diferencas = '{}'::jsonb THEN RETURN NULL; END IF;
    evento_id := COALESCE((depois->>'id_evento')::integer, (antes->>'id_evento')::integer);
    evento_anterior := (antes->>'id_evento')::integer;
    entidade_id := CASE WHEN tipo = 'evento' THEN evento_id
        ELSE COALESCE((depois->>'id_evento_percurso')::integer,(antes->>'id_evento_percurso')::integer) END;
    INSERT INTO public.tb_evento_fatos_historico
        (entidade,id_entidade,id_evento,id_evento_anterior,operacao,alteracoes)
    VALUES (tipo,entidade_id,evento_id,evento_anterior,TG_OP,diferencas);
    RETURN NULL; -- AFTER trigger: never rewrites the originating row.
END;
$function$
